# =====================================================================
#  LOGO (znak "SK" z wizytowki Google - ikona okna i paska zadan, obraz na banerze)
# =====================================================================
$LogoIkonaB64 = ''
$LogoBanerB64 = ''

function Ikona-Logo {
    try {
        $strumien = New-Object System.IO.MemoryStream(,[Convert]::FromBase64String($LogoIkonaB64))
        return New-Object System.Drawing.Icon($strumien)
    } catch { return $null }
}

function Obraz-Logo {
    try {
        $strumien = New-Object System.IO.MemoryStream(,[Convert]::FromBase64String($LogoBanerB64))
        return [System.Drawing.Image]::FromStream($strumien)
    } catch { return $null }
}

# =====================================================================
#  DANE: USLUGI
