function Nowa-Usluga($nazwa, $kategoria, $etykieta, $opis, $rodzaj, $domyslnie) {
    [pscustomobject]@{ Nazwa = $nazwa; Kategoria = $kategoria; Etykieta = $etykieta; Opis = $opis; Rodzaj = $rodzaj; Domyslnie = $domyslnie }
}
