# =====================================================================
#  DANE: KOPIA PRZED REINSTALACJA
# =====================================================================
function Nowa-Kopia($etykieta, $opis, $zaznacz, $klucz, $cel, $akcja) {
    [pscustomobject]@{ Etykieta = $etykieta; Opis = $opis; Zaznacz = $zaznacz; Klucz = $klucz; Zrodlo = ''; Cel = $cel; Akcja = $akcja; Bajty = [long]-1 }
}

$listaKopii = @(
    Nowa-Kopia 'Sterowniki' 'Wszystkie zainstalowane sterowniki producentów. Po reinstalacji: Menedżer urządzeń > Aktualizuj sterownik > wskaż ten folder.' $true '' 'Sterowniki' {
        param($el, $cel)
        New-Item -ItemType Directory -Force -Path $cel | Out-Null
        $w = Uruchom-Program ('dism.exe /Online /Export-Driver /Destination:"' + $cel + '"') 'eksport sterowników'
        $ile = @(Get-ChildItem -LiteralPath $cel -Directory -ErrorAction SilentlyContinue).Count
        if ($w.Kod -eq 0) { 'skopiowano sterowników: ' + $ile } else { 'błąd, kod ' + $w.Kod }
    }
    Nowa-Kopia 'Lista zainstalowanych programów' 'Plik z listą programów, żeby po reinstalacji niczego nie zapomnieć.' $true '' 'Programy' {
        param($el, $cel)
        New-Item -ItemType Directory -Force -Path $cel | Out-Null
        $lista = @(Lista-Programow)
        $lista | Export-Csv -LiteralPath (Join-Path $cel 'Programy.csv') -NoTypeInformation -Encoding UTF8
        $linie = @($lista | ForEach-Object { $_.Nazwa + '   ' + $_.Wersja + '   (' + $_.Wydawca + ')' })
        $linie | Out-File -FilePath (Join-Path $cel 'Programy.txt') -Encoding UTF8
        'zapisano programów: ' + $lista.Count
    }
    Nowa-Kopia 'Informacje o komputerze i klucz Windows' 'Model, procesor, pamięć, dyski i klucz Windows z BIOS/UEFI (jeśli jest).' $true '' 'Komputer' {
        param($el, $cel)
        New-Item -ItemType Directory -Force -Path $cel | Out-Null
        if (@($stan.Sprzet).Count -eq 0) { $stan.Sprzet = @(Sprawdz-Sprzet) }
        $linie = New-Object System.Collections.ArrayList
        [void]$linie.Add('Komputer: ' + $env:COMPUTERNAME + '   ' + (Get-Date -Format 'yyyy-MM-dd HH:mm'))
        if ($infoOS) { [void]$linie.Add('System: ' + $infoOS) }
        if ($stan.KluczWindows) { [void]$linie.Add('Klucz Windows z BIOS/UEFI: ' + $stan.KluczWindows) }
        [void]$linie.Add('')
        foreach ($w in $stan.Sprzet) { [void]$linie.Add($w.Nazwa + ': ' + $w.Wynik) }
        $linie | Out-File -FilePath (Join-Path $cel 'Komputer.txt') -Encoding UTF8
        'zapisano'
    }
    Nowa-Kopia 'Zakładki przeglądarek' 'Zakładki Chrome, Edge, Brave, Opery i Firefoksa wybranego konta.' $true '' 'Zakladki' {
        param($el, $cel)
        New-Item -ItemType Directory -Force -Path $cel | Out-Null
        $ile = 0
        $profil = $stan.ProfilKopii.Sciezka
        $chromowe = @(
            @{ Nazwa = 'Chrome'; Sciezka = Join-Path $profil 'AppData\Local\Google\Chrome\User Data' }
            @{ Nazwa = 'Edge'; Sciezka = Join-Path $profil 'AppData\Local\Microsoft\Edge\User Data' }
            @{ Nazwa = 'Brave'; Sciezka = Join-Path $profil 'AppData\Local\BraveSoftware\Brave-Browser\User Data' }
            @{ Nazwa = 'Opera'; Sciezka = Join-Path $profil 'AppData\Roaming\Opera Software\Opera Stable' }
        )
        foreach ($p in $chromowe) {
            if (-not (Test-Path -LiteralPath $p.Sciezka)) { continue }
            foreach ($plik in @(Get-ChildItem -Path (Join-Path $p.Sciezka '*\Bookmarks') -File -ErrorAction SilentlyContinue) + @(Get-ChildItem -Path (Join-Path $p.Sciezka 'Bookmarks') -File -ErrorAction SilentlyContinue)) {
                $profil = Split-Path -Path (Split-Path -Path $plik.FullName -Parent) -Leaf
                Copy-Item -LiteralPath $plik.FullName -Destination (Join-Path $cel ($p.Nazwa + '_' + $profil + '_Bookmarks.json')) -Force
                $ile++
            }
        }
        $ff = Join-Path $profil 'AppData\Roaming\Mozilla\Firefox\Profiles'
        foreach ($prof in @(Get-ChildItem -LiteralPath $ff -Directory -ErrorAction SilentlyContinue)) {
            $kopie = Join-Path $prof.FullName 'bookmarkbackups'
            if (Test-Path -LiteralPath $kopie) {
                Copy-Item -LiteralPath $kopie -Destination (Join-Path $cel ('Firefox_' + $prof.Name)) -Recurse -Force
                $ile++
            }
        }
        'skopiowano zestawów zakładek: ' + $ile
    }
    Nowa-Kopia 'Pulpit' 'Pliki z pulpitu.' $false 'Pulpit' 'Pulpit' $null
    Nowa-Kopia 'Dokumenty' 'Folder Dokumenty. Pliki z OneDrive dostępne tylko w chmurze zostaną pobrane.' $false 'Dokumenty' 'Dokumenty' $null
    Nowa-Kopia 'Obrazy' 'Zdjęcia i obrazy.' $false 'Obrazy' 'Obrazy' $null
    Nowa-Kopia 'Pobrane' 'Folder Pobrane.' $false 'Pobrane' 'Pobrane' $null
    Nowa-Kopia 'Muzyka' 'Folder Muzyka.' $false 'Muzyka' 'Muzyka' $null
    Nowa-Kopia 'Wideo' 'Folder Wideo.' $false 'Wideo' 'Wideo' $null
)

# =====================================================================
#  FUNKCJE: USLUGI
# =====================================================================
function Get-StartInfo([string]$nazwa) {
    $klucz = "HKLM:\SYSTEM\CurrentControlSet\Services\$nazwa"
    if (-not (Test-Path -LiteralPath $klucz)) { return $null }
    $p = Get-ItemProperty -LiteralPath $klucz -ErrorAction SilentlyContinue
    if (-not $p) { return $null }
    $opozniony = 0
    if ($p.PSObject.Properties['DelayedAutostart']) { $opozniony = [int]$p.DelayedAutostart }
    [pscustomobject]@{ Start = [int]$p.Start; Delayed = $opozniony }
}

function Opis-Startu([int]$start, [int]$opozniony) {
    switch ($start) {
        2       { if ($opozniony -eq 1) { 'Automatyczny (opóźniony)' } else { 'Automatyczny' } }
        3       { 'Ręczny' }
        4       { 'Wyłączony' }
        default { "Inny ($start)" }
    }
}

function Stan-PL($status) {
    switch ([string]$status) {
        'Running' { 'Działa' }
        'Stopped' { 'Zatrzymana' }
        default   { [string]$status }
    }
}

function Typ-Z-Kopii($start, $opozniony) {
    switch ([int]$start) {
        2       { if ([int]$opozniony -eq 1) { 'delayed-auto' } else { 'auto' } }
        3       { 'demand' }
        4       { 'disabled' }
        default { $null }
    }
}

function Ustaw-Start([string]$nazwa, [string]$typ) {
    $wynik = & sc.exe config $nazwa start= $typ 2>&1
    $kodWyjscia = $LASTEXITCODE
    [pscustomobject]@{ Ok = ($kodWyjscia -eq 0); Komunikat = ($wynik -join ' ') }
}

# =====================================================================
#  FUNKCJE: CZYSZCZENIE
# =====================================================================
function Rozmiar-Sciezek([string[]]$wzorce) {
    $suma = [long]0
    foreach ($w in $wzorce) {
        foreach ($el in @(Get-ChildItem -Path $w -Force -ErrorAction SilentlyContinue)) {
            if ($el.PSIsContainer) {
                $s = (Get-ChildItem -LiteralPath $el.FullName -Recurse -Force -File -ErrorAction SilentlyContinue |
                    Measure-Object -Property Length -Sum).Sum
            } else {
                $s = $el.Length
            }
            if ($s) { $suma += [long]$s }
        }
    }
    $suma
}

function Usun-Sciezki([string[]]$wzorce) {
    foreach ($w in $wzorce) {
        foreach ($el in @(Get-ChildItem -Path $w -Force -ErrorAction SilentlyContinue)) {
            Remove-Item -LiteralPath $el.FullName -Recurse -Force -ErrorAction SilentlyContinue
        }
    }
}

# =====================================================================
#  FUNKCJE: AUTOSTART
# =====================================================================
$kluczZatw = 'Software\Microsoft\Windows\CurrentVersion\Explorer\StartupApproved'

function Czy-Wylaczony([string]$klucz, [string]$wartosc) {
    if (-not (Test-Path -LiteralPath $klucz)) { return $false }
    $v = (Get-Item -LiteralPath $klucz).GetValue($wartosc)
    if ($v -is [byte[]] -and $v.Length -gt 0) { return (($v[0] -band 1) -eq 1) }
    $false
}

function Pobierz-Autostart {
    $wynik = New-Object System.Collections.ArrayList
    $rejestr = @(
        @{ Klucz = (Mapuj-Klucz 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Run'); Zatw = (Mapuj-Klucz "HKCU:\$kluczZatw\Run"); Miejsce = 'Rejestr (użytkownik)' }
        @{ Klucz = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Run';             Zatw = "HKLM:\$kluczZatw\Run";   Miejsce = 'Rejestr (wszyscy)' }
        @{ Klucz = 'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Run'; Zatw = "HKLM:\$kluczZatw\Run32"; Miejsce = 'Rejestr 32-bit (wszyscy)' }
    )
    foreach ($z in $rejestr) {
        if (-not (Test-Path -LiteralPath $z.Klucz)) { continue }
        $k = Get-Item -LiteralPath $z.Klucz
        foreach ($nazwa in $k.GetValueNames()) {
            if (-not $nazwa) { continue }
            [void]$wynik.Add([pscustomobject]@{
                Nazwa = $nazwa; Wartosc = $nazwa; Polecenie = [string]$k.GetValue($nazwa)
                Miejsce = $z.Miejsce; Zatw = $z.Zatw; Wylaczony = (Czy-Wylaczony $z.Zatw $nazwa)
            })
        }
    }
    $folderStartu = [Environment]::GetFolderPath('Startup')
    if ($stan.InneKonto -and $stan.Klient) { $folderStartu = Join-Path $stan.Klient.Sciezka 'AppData\Roaming\Microsoft\Windows\Start Menu\Programs\Startup' }
    $foldery = @(
        @{ Sciezka = $folderStartu; Zatw = (Mapuj-Klucz "HKCU:\$kluczZatw\StartupFolder"); Miejsce = 'Folder Autostart (użytkownik)' }
        @{ Sciezka = [Environment]::GetFolderPath('CommonStartup'); Zatw = "HKLM:\$kluczZatw\StartupFolder"; Miejsce = 'Folder Autostart (wszyscy)' }
    )
    foreach ($f in $foldery) {
        if (-not $f.Sciezka -or -not (Test-Path -LiteralPath $f.Sciezka)) { continue }
        foreach ($plik in @(Get-ChildItem -LiteralPath $f.Sciezka -File -Force -ErrorAction SilentlyContinue)) {
            if ($plik.Name -eq 'desktop.ini') { continue }
            [void]$wynik.Add([pscustomobject]@{
                Nazwa = $plik.BaseName; Wartosc = $plik.Name; Polecenie = $plik.FullName
                Miejsce = $f.Miejsce; Zatw = $f.Zatw; Wylaczony = (Czy-Wylaczony $f.Zatw $plik.Name)
            })
        }
    }
    $wynik
}

function Ustaw-Autostart($el, [bool]$wlacz) {
    if (-not (Test-Path -LiteralPath $el.Zatw)) { New-Item -Path $el.Zatw -Force | Out-Null }
    $bajty = New-Object byte[] 12
    if ($wlacz) {
        $bajty[0] = 2
    } else {
        $bajty[0] = 3
        $czas = [BitConverter]::GetBytes((Get-Date).ToFileTime())
        [Array]::Copy($czas, 0, $bajty, 4, 8)
    }
    Set-ItemProperty -LiteralPath $el.Zatw -Name $el.Wartosc -Value $bajty -Type Binary
}

# =====================================================================
#  FUNKCJE: PROGRAMY W TLE
# =====================================================================
$chronione = @('powershell', 'pwsh', 'MsMpEng', 'NisSrv', 'SecurityHealthService', 'MpDefenderCoreService', 'smartscreen')
$kluczPolityki = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\AppPrivacy'

function Pobierz-Procesy {
    $windows = $env:windir
    $lista = @(Get-Process | Where-Object {
        $_.Id -ne $PID -and $_.Path -and
        (-not $_.Path.StartsWith($windows, [StringComparison]::OrdinalIgnoreCase)) -and
        ($chronione -notcontains $_.ProcessName)
    })
    $wynik = foreach ($g in ($lista | Group-Object -Property ProcessName)) {
        $pierwszy = $g.Group[0]
        $opis = ''
        try { $opis = [string]$pierwszy.Description } catch { }
        if (-not $opis) { try { $opis = [string]$pierwszy.Company } catch { } }
        $pamiec = ($g.Group | Measure-Object -Property WorkingSet64 -Sum).Sum
        $okna = @($g.Group | Where-Object { $_.MainWindowHandle -ne [IntPtr]::Zero }).Count
        [pscustomobject]@{
            Nazwa = $g.Name; Opis = $opis; Liczba = $g.Count; Pamiec = [long]$pamiec
            Sciezka = $pierwszy.Path; Okno = ($okna -gt 0)
        }
    }
    @($wynik | Sort-Object -Property Pamiec -Descending)
}

function Czy-TloZablokowane {
    if (-not (Test-Path -LiteralPath $kluczPolityki)) { return $false }
    $v = (Get-Item -LiteralPath $kluczPolityki).GetValue('LetAppsRunInBackground')
    return ($v -eq 2)
}

# =====================================================================
#  FUNKCJE: BEZPIECZENSTWO
# =====================================================================
function Wynik-Sprawdzenia($nazwa, $wynik, $ocena, $rada) {
    $waga = switch ($ocena) { 'ŹLE' { 0 } 'UWAGA' { 1 } 'INFO' { 2 } default { 3 } }
    [pscustomobject]@{ Nazwa = $nazwa; Wynik = $wynik; Ocena = $ocena; Rada = $rada; Waga = $waga }
}

function Sprawdz-Bezpieczenstwo {
    $wyniki = New-Object System.Collections.ArrayList
    $os = $null
    try { $os = Get-CimInstance -ClassName Win32_OperatingSystem -ErrorAction Stop } catch { }

    # System
    try {
        $build = [int]$os.BuildNumber
        if ($build -lt 22000) {
            [void]$wyniki.Add((Wynik-Sprawdzenia 'Wersja Windows' "$($os.Caption) (kompilacja $build)" 'ŹLE' 'Windows 10 nie ma już wsparcia Microsoft (od 14.10.2025) - zalecana aktualizacja do Windows 11 albo nowszy sprzęt.'))
        } else {
            [void]$wyniki.Add((Wynik-Sprawdzenia 'Wersja Windows' "$($os.Caption) (kompilacja $build)" 'OK' ''))
        }
    } catch { [void]$wyniki.Add((Wynik-Sprawdzenia 'Wersja Windows' 'nie udało się sprawdzić' 'UWAGA' '')) }

    # Antywirus (Centrum zabezpieczen)
    try {
        $av = @(Get-CimInstance -Namespace 'root/SecurityCenter2' -ClassName AntiVirusProduct -ErrorAction Stop)
        $aktywne = @($av | Where-Object { ([int]$_.productState -band 0x1000) -ne 0 })
        $stare = @($aktywne | Where-Object { ([int]$_.productState -band 0x10) -ne 0 })
        if ($aktywne.Count -eq 0) {
            [void]$wyniki.Add((Wynik-Sprawdzenia 'Antywirus' 'brak aktywnego antywirusa' 'ŹLE' 'Włącz Microsoft Defender albo zainstalowany antywirus.'))
        } elseif ($stare.Count -gt 0) {
            [void]$wyniki.Add((Wynik-Sprawdzenia 'Antywirus' (($aktywne.displayName) -join ', ') 'UWAGA' 'Bazy wirusów są nieaktualne - należy je zaktualizować.'))
        } else {
            [void]$wyniki.Add((Wynik-Sprawdzenia 'Antywirus' ((($aktywne.displayName) -join ', ') + ' - aktywny, aktualny') 'OK' ''))
        }
    } catch { [void]$wyniki.Add((Wynik-Sprawdzenia 'Antywirus' 'nie udało się sprawdzić' 'UWAGA' '')) }

    # Defender
    try {
        $mp = Get-MpComputerStatus -ErrorAction Stop
        $txt = 'ochrona w czasie rzeczywistym: ' + $(if ($mp.RealTimeProtectionEnabled) { 'włączona' } else { 'wyłączona' }) +
            "; bazy sprzed $($mp.AntivirusSignatureAge) dni; szybkie skanowanie: $($mp.QuickScanAge) dni temu"
        if (-not $mp.RealTimeProtectionEnabled) {
            [void]$wyniki.Add((Wynik-Sprawdzenia 'Microsoft Defender' $txt 'INFO' 'Wyłączony - w porządku, jeśli działa inny antywirus (patrz wyżej).'))
        } elseif ($mp.AntivirusSignatureAge -gt 3) {
            [void]$wyniki.Add((Wynik-Sprawdzenia 'Microsoft Defender' $txt 'UWAGA' 'Bazy antywirusa są nieaktualne - należy je zaktualizować.'))
        } else {
            [void]$wyniki.Add((Wynik-Sprawdzenia 'Microsoft Defender' $txt 'OK' ''))
        }
    } catch { [void]$wyniki.Add((Wynik-Sprawdzenia 'Microsoft Defender' 'niedostępny (prawdopodobnie inny antywirus)' 'INFO' '')) }

    # Zapora
    try {
        $profile = @(Get-NetFirewallProfile -ErrorAction Stop)
        $wylaczone = @($profile | Where-Object { -not $_.Enabled })
        $txt = ($profile | ForEach-Object { $_.Name + ': ' + $(if ($_.Enabled) { 'wł.' } else { 'WYŁ.' }) }) -join ', '
        if ($wylaczone.Count -gt 0) {
            [void]$wyniki.Add((Wynik-Sprawdzenia 'Zapora Windows' $txt 'ŹLE' 'Zapora powinna być włączona (chyba że działa zapora innego programu).'))
        } else {
            [void]$wyniki.Add((Wynik-Sprawdzenia 'Zapora Windows' $txt 'OK' ''))
        }
    } catch { [void]$wyniki.Add((Wynik-Sprawdzenia 'Zapora Windows' 'nie udało się sprawdzić' 'UWAGA' '')) }

    # Aktualizacje
    try {
        $ostatnia = Get-HotFix -ErrorAction Stop | Where-Object { $_.InstalledOn } | Sort-Object -Property InstalledOn -Descending | Select-Object -First 1
        if ($ostatnia) {
            $dni = [int]((Get-Date) - $ostatnia.InstalledOn).TotalDays
            $txt = "ostatnia: $($ostatnia.HotFixID), $dni dni temu"
            if ($dni -gt 90) { $ocena = 'ŹLE' } elseif ($dni -gt 45) { $ocena = 'UWAGA' } else { $ocena = 'OK' }
            $rada = ''
            if ($ocena -ne 'OK') { $rada = 'Zalecana instalacja aktualizacji Windows.' }
            [void]$wyniki.Add((Wynik-Sprawdzenia 'Aktualizacje Windows' $txt $ocena $rada))
        } else {
            [void]$wyniki.Add((Wynik-Sprawdzenia 'Aktualizacje Windows' 'brak danych' 'UWAGA' 'Sprawdź Windows Update ręcznie.'))
        }
    } catch { [void]$wyniki.Add((Wynik-Sprawdzenia 'Aktualizacje Windows' 'nie udało się sprawdzić' 'UWAGA' '')) }

    # Restart
    try {
        $dniOdStartu = [int]((Get-Date) - $os.LastBootUpTime).TotalDays
        if ($dniOdStartu -gt 14) {
            [void]$wyniki.Add((Wynik-Sprawdzenia 'Ostatni restart' "$dniOdStartu dni temu" 'UWAGA' 'Zalecane ponowne uruchomienie, żeby dokończyć aktualizacje.'))
        } else {
            [void]$wyniki.Add((Wynik-Sprawdzenia 'Ostatni restart' "$dniOdStartu dni temu" 'OK' ''))
        }
    } catch { }

    # UAC
    try {
        $sys = Get-ItemProperty -LiteralPath 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System' -ErrorAction Stop
        if ($sys.EnableLUA -ne 1) {
            [void]$wyniki.Add((Wynik-Sprawdzenia 'Kontrola konta (UAC)' 'wyłączona' 'ŹLE' 'Włącz UAC: Panel sterowania > Konta użytkowników > Zmień ustawienia kontroli konta.'))
        } elseif ($sys.ConsentPromptBehaviorAdmin -eq 0) {
            [void]$wyniki.Add((Wynik-Sprawdzenia 'Kontrola konta (UAC)' 'włączona, ale bez powiadomień' 'UWAGA' 'Ustaw poziom UAC na domyślny.'))
        } else {
            [void]$wyniki.Add((Wynik-Sprawdzenia 'Kontrola konta (UAC)' 'włączona' 'OK' ''))
        }
    } catch { [void]$wyniki.Add((Wynik-Sprawdzenia 'Kontrola konta (UAC)' 'nie udało się sprawdzić' 'UWAGA' '')) }

    # Pulpit zdalny
    try {
        $ts = Get-ItemProperty -LiteralPath 'HKLM:\SYSTEM\CurrentControlSet\Control\Terminal Server' -ErrorAction Stop
        if ($ts.fDenyTSConnections -eq 0) {
            [void]$wyniki.Add((Wynik-Sprawdzenia 'Pulpit zdalny (RDP)' 'włączony' 'UWAGA' 'Wyłącz, jeśli klient go nie używa (Ustawienia > System > Pulpit zdalny).'))
        } else {
            [void]$wyniki.Add((Wynik-Sprawdzenia 'Pulpit zdalny (RDP)' 'wyłączony' 'OK' ''))
        }
    } catch { }

    # SMBv1
    try {
        $smb = Get-SmbServerConfiguration -ErrorAction Stop
        if ($smb.EnableSMB1Protocol) {
            [void]$wyniki.Add((Wynik-Sprawdzenia 'Protokół SMBv1' 'włączony' 'ŹLE' 'Przestarzały i niebezpieczny protokół (wykorzystywany przez wirusa WannaCry) - zalecane wyłączenie.'))
        } else {
            [void]$wyniki.Add((Wynik-Sprawdzenia 'Protokół SMBv1' 'wyłączony' 'OK' ''))
        }
    } catch { }

    # Secure Boot
    try {
        if (Confirm-SecureBootUEFI -ErrorAction Stop) {
            [void]$wyniki.Add((Wynik-Sprawdzenia 'Secure Boot' 'włączony' 'OK' ''))
        } else {
            [void]$wyniki.Add((Wynik-Sprawdzenia 'Secure Boot' 'wyłączony' 'UWAGA' 'Włącz w ustawieniach UEFI/BIOS.'))
        }
    } catch { [void]$wyniki.Add((Wynik-Sprawdzenia 'Secure Boot' 'nieobsługiwany (tryb BIOS/Legacy)' 'INFO' '')) }

    # TPM
    try {
        $tpm = Get-Tpm -ErrorAction Stop
        if ($tpm.TpmPresent -and $tpm.TpmReady) {
            [void]$wyniki.Add((Wynik-Sprawdzenia 'Moduł TPM' 'obecny i gotowy' 'OK' ''))
        } elseif ($tpm.TpmPresent) {
            [void]$wyniki.Add((Wynik-Sprawdzenia 'Moduł TPM' 'obecny, niegotowy' 'UWAGA' 'Sprawdź ustawienia TPM w UEFI.'))
        } else {
            [void]$wyniki.Add((Wynik-Sprawdzenia 'Moduł TPM' 'brak lub wyłączony w UEFI' 'INFO' 'Potrzebny do Windows 11 i BitLockera.'))
        }
    } catch { }

    # BitLocker
    try {
        $bl = Get-BitLockerVolume -MountPoint 'C:' -ErrorAction Stop
        if ([string]$bl.ProtectionStatus -eq 'On') {
            [void]$wyniki.Add((Wynik-Sprawdzenia 'Szyfrowanie dysku C:' 'BitLocker włączony' 'OK' 'Upewnij się, że klient ma zapisany klucz odzyskiwania!'))
        } else {
            [void]$wyniki.Add((Wynik-Sprawdzenia 'Szyfrowanie dysku C:' 'dysk niezaszyfrowany' 'INFO' 'Na laptopach warto włączyć szyfrowanie.'))
        }
    } catch { [void]$wyniki.Add((Wynik-Sprawdzenia 'Szyfrowanie dysku C:' 'BitLocker niedostępny (np. Windows Home)' 'INFO' '')) }

    # Konta
    try {
        $gosc = Get-LocalUser -ErrorAction Stop | Where-Object { $_.SID.Value -like '*-501' }
        if ($gosc -and $gosc.Enabled) {
            [void]$wyniki.Add((Wynik-Sprawdzenia 'Konto Gość' 'włączone' 'ŹLE' ('Konto Gość powinno być wyłączone (Disable-LocalUser -SID ' + $gosc.SID.Value + ').')))
        } else {
            [void]$wyniki.Add((Wynik-Sprawdzenia 'Konto Gość' 'wyłączone' 'OK' ''))
        }
        $adm = Get-LocalUser | Where-Object { $_.SID.Value -like '*-500' }
        if ($adm -and $adm.Enabled) {
            [void]$wyniki.Add((Wynik-Sprawdzenia 'Wbudowane konto Administrator' 'włączone' 'UWAGA' 'Zwykle powinno być wyłączone; sprawdź, czy ma silne hasło.'))
        }
    } catch { }

    $wyniki
}

# =====================================================================
#  FUNKCJE: SPRZET
# =====================================================================
function Typ-Pamieci([int]$smbios, [int]$typ) {
    $mapaSmbios = @{ 18 = 'DDR'; 19 = 'DDR2'; 24 = 'DDR3'; 26 = 'DDR4'; 27 = 'LPDDR'; 28 = 'LPDDR2'; 29 = 'LPDDR3'; 30 = 'LPDDR4'; 34 = 'DDR5'; 35 = 'LPDDR5' }
    $mapaStara = @{ 20 = 'DDR'; 21 = 'DDR2'; 24 = 'DDR3' }
    if ($mapaSmbios.ContainsKey($smbios)) { return $mapaSmbios[$smbios] }
    if ($mapaStara.ContainsKey($typ)) { return $mapaStara[$typ] }
    ''
}

function Opis-BleduUrzadzenia($kod) {
    switch ([int]$kod) {
        1       { 'źle skonfigurowane' }
        3       { 'uszkodzony sterownik' }
        10      { 'nie może się uruchomić' }
        18      { 'sterownik do ponownej instalacji' }
        28      { 'brak sterownika' }
        31      { 'nie działa poprawnie' }
        43      { 'zgłosiło problem (kod 43)' }
        default { 'kod błędu ' + $kod }
    }
}

function Pobierz-CzasyStartu {
    $wynik = New-Object System.Collections.ArrayList
    $zdarzenia = @(Get-WinEvent -FilterHashtable @{ LogName = 'Microsoft-Windows-Diagnostics-Performance/Operational'; Id = 100 } -MaxEvents 40 -ErrorAction Stop)
    foreach ($z in $zdarzenia) {
        $x = [xml]$z.ToXml()
        $ms = 0
        foreach ($d in @($x.Event.EventData.Data)) { if ($d.Name -eq 'BootTime') { $ms = [double]$d.'#text' } }
        if ($ms -gt 0) { [void]$wynik.Add([pscustomobject]@{ Data = $z.TimeCreated; Sekundy = [int][math]::Round($ms / 1000) }) }
    }
    $wynik
}

function Podsumuj-CzasStartu($czasy, $poczatek) {
    $lista = @($czasy | Where-Object { $_ } | Sort-Object -Property Data)
    if ($lista.Count -eq 0) { return $null }
    $ostatni = $lista[-1]
    $przed = $null; $po = $null
    if ($poczatek) {
        $p1 = @($lista | Where-Object { $_.Data -lt $poczatek } | Select-Object -Last 3)
        $p2 = @($lista | Where-Object { $_.Data -ge $poczatek })
        if ($p1.Count -gt 0) { $przed = [int][math]::Round(($p1 | Measure-Object -Property Sekundy -Average).Average) }
        if ($p2.Count -gt 0) { $po = $p2[-1].Sekundy }
    }
    $ostatnie = @($lista | Select-Object -Last 5)
    $srednio = [int][math]::Round(($ostatnie | Measure-Object -Property Sekundy -Average).Average)
    [pscustomobject]@{ Ostatni = $ostatni.Sekundy; Kiedy = $ostatni.Data; Srednio = $srednio; Przed = $przed; Po = $po }
}

function Sprawdz-Sprzet {
    $wyniki = New-Object System.Collections.ArrayList
    $os = $null; $cs = $null
    try { $os = Get-CimInstance -ClassName Win32_OperatingSystem -ErrorAction Stop } catch { }
    try { $cs = Get-CimInstance -ClassName Win32_ComputerSystem -ErrorAction Stop } catch { }

    # Komputer, BIOS, numer seryjny
    try {
        $bios = Get-CimInstance -ClassName Win32_BIOS -ErrorAction Stop
        $plyta = Get-CimInstance -ClassName Win32_BaseBoard -ErrorAction SilentlyContinue | Select-Object -First 1
        $txt = (([string]$cs.Manufacturer).Trim() + ' ' + ([string]$cs.Model).Trim()).Trim()
        if ($plyta) { $txt = $txt + '; płyta: ' + (([string]$plyta.Manufacturer).Trim() + ' ' + ([string]$plyta.Product).Trim()).Trim() }
        $txt = $txt + '; BIOS ' + $bios.SMBIOSBIOSVersion
        if ($bios.ReleaseDate) { $txt = $txt + ' z ' + $bios.ReleaseDate.ToString('yyyy-MM-dd') }
        [void]$wyniki.Add((Wynik-Sprawdzenia 'Komputer' $txt 'INFO' ''))
        $sn = ([string]$bios.SerialNumber).Trim()
        if ($sn -and $sn -notmatch 'To be filled|Default|System Serial|^0+$') {
            [void]$wyniki.Add((Wynik-Sprawdzenia 'Numer seryjny' $sn 'INFO' 'Do sprawdzenia gwarancji i sterowników na stronie producenta.'))
        }
    } catch { }

    # Procesor
    try {
        $c = @(Get-CimInstance -ClassName Win32_Processor -ErrorAction Stop)[0]
        $txt = (([string]$c.Name) -replace '\s+', ' ').Trim() + '; rdzenie: ' + $c.NumberOfCores + ', wątki: ' + $c.NumberOfLogicalProcessors
        [void]$wyniki.Add((Wynik-Sprawdzenia 'Procesor' $txt 'INFO' ''))
    } catch { }

    # Pamiec RAM
    try {
        $moduly = @(Get-CimInstance -ClassName Win32_PhysicalMemory -ErrorAction Stop)
        $tablice = @(Get-CimInstance -ClassName Win32_PhysicalMemoryArray -ErrorAction SilentlyContinue | Where-Object { $_.Use -eq 3 })
        $sloty = [int](($tablice | Measure-Object -Property MemoryDevices -Sum).Sum)
        $bajty = [double](($moduly | Measure-Object -Property Capacity -Sum).Sum)
        if ($bajty -le 0 -and $cs) { $bajty = [double]$cs.TotalPhysicalMemory }
        $gb = [math]::Round($bajty / 1GB)
        $typ = ''; $mhz = 0
        if ($moduly.Count -gt 0) {
            $typ = Typ-Pamieci ([int]$moduly[0].SMBIOSMemoryType) ([int]$moduly[0].MemoryType)
            $mhz = [int]$moduly[0].ConfiguredClockSpeed
            if (-not $mhz) { $mhz = [int]$moduly[0].Speed }
        }
        $txt = [string]$gb + ' GB'
        if ($typ) { $txt = $txt + ' ' + $typ }
        if ($mhz) { $txt = $txt + ' ' + $mhz + ' MHz' }
        if ($moduly.Count -gt 0) { $txt = $txt + ' (' + (($moduly | ForEach-Object { [string][math]::Round($_.Capacity / 1GB) + ' GB' }) -join ' + ') + ')' }
        $wolne = 0
        if ($sloty -gt 0 -and $sloty -ge $moduly.Count) {
            $wolne = $sloty - $moduly.Count
            $txt = $txt + '; sloty: zajęte ' + $moduly.Count + ' z ' + $sloty
        }
        if ($gb -lt 4) { $ocena = 'ŹLE'; $rada = 'Za mało pamięci na współczesny Windows - zalecana rozbudowa do co najmniej 8 GB.' }
        elseif ($gb -lt 8) { $ocena = 'UWAGA'; $rada = 'Do Windows 11 i przeglądarki zalecane 8-16 GB. Rozbudowa wyraźnie przyspieszy komputer.' }
        elseif ($gb -lt 16 -and $wolne -gt 0) { $ocena = 'INFO'; $rada = 'Wolne sloty: ' + $wolne + ' - łatwa rozbudowa, gdy klient potrzebuje więcej.' }
        else { $ocena = 'OK'; $rada = '' }
        if (($ocena -eq 'ŹLE' -or $ocena -eq 'UWAGA') -and $wolne -gt 0) { $rada = $rada + ' Wolne sloty: ' + $wolne + '.' }
        [void]$wyniki.Add((Wynik-Sprawdzenia 'Pamięć RAM' $txt $ocena $rada))
    } catch { }

    # Dyski
    $systemowy = ''
    try { $systemowy = [string](Get-Partition -DriveLetter ($env:SystemDrive.Substring(0, 1)) -ErrorAction Stop).DiskNumber } catch { }
    try {
        $dyski = @(Get-PhysicalDisk -ErrorAction Stop | Where-Object { [string]$_.BusType -ne 'USB' } | Sort-Object -Property DeviceId)
        foreach ($d in $dyski) {
            $rel = $null
            try { $rel = $d | Get-StorageReliabilityCounter -ErrorAction Stop } catch { }
            $bus = [string]$d.BusType
            $typ = [string]$d.MediaType
            if ($typ -ne 'SSD' -and $typ -ne 'HDD') { if ($bus -eq 'NVMe') { $typ = 'SSD' } else { $typ = 'dysk' } }
            $czySys = ([string]$d.DeviceId -eq $systemowy)
            $nazwa = 'Dysk ' + $d.DeviceId
            if ($czySys) { $nazwa = $nazwa + ' (systemowy)' }
            $txt = ([string]$d.FriendlyName).Trim() + '; ' + $typ + ' ' + $bus + ', ' + [math]::Round($d.Size / 1GB) + ' GB; stan: ' + [string]$d.HealthStatus
            $ocena = 'OK'
            $rady = New-Object System.Collections.ArrayList
            if ([string]$d.HealthStatus -eq 'Unhealthy') { $ocena = 'ŹLE'; [void]$rady.Add('Dysk zgłasza awarię - pilnie potrzebna kopia danych i wymiana dysku.') }
            elseif ([string]$d.HealthStatus -eq 'Warning') { $ocena = 'UWAGA'; [void]$rady.Add('Dysk zgłasza ostrzeżenie - zalecana kopia danych i rozważenie wymiany.') }
            if ($rel) {
                if ($rel.Temperature -gt 0) { $txt = $txt + '; temp. ' + $rel.Temperature + ' °C' }
                if ($typ -eq 'SSD' -and $null -ne $rel.Wear) { $txt = $txt + '; zużycie ' + $rel.Wear + '%' }
                if ($rel.PowerOnHours -gt 0) { $txt = $txt + '; przepracował ' + $rel.PowerOnHours + ' h' }
                if ($rel.Wear -ge 90) { $ocena = 'ŹLE'; [void]$rady.Add('Dysk SSD prawie zużyty - zalecana wymiana.') }
                elseif ($rel.Wear -ge 70) { if ($ocena -eq 'OK') { $ocena = 'UWAGA' }; [void]$rady.Add('Dysk SSD mocno zużyty - warto zaplanować wymianę.') }
                if ($rel.Temperature -ge 60) { if ($ocena -eq 'OK') { $ocena = 'UWAGA' }; [void]$rady.Add('Wysoka temperatura dysku - zalecane sprawdzenie chłodzenia.') }
                if ($rel.ReadErrorsUncorrected -gt 0) { if ($ocena -eq 'OK') { $ocena = 'UWAGA' }; [void]$rady.Add('Dysk ma nienaprawialne błędy odczytu - zalecana kopia danych.') }
            }
            if ($typ -eq 'HDD' -and $czySys) {
                if ($ocena -eq 'OK') { $ocena = 'UWAGA' }
                [void]$rady.Add('System na dysku talerzowym (HDD) - wymiana na SSD przyspieszy komputer kilkukrotnie.')
            }
            [void]$wyniki.Add((Wynik-Sprawdzenia $nazwa $txt $ocena ($rady -join ' ')))
        }
    } catch { [void]$wyniki.Add((Wynik-Sprawdzenia 'Dyski' 'nie udało się sprawdzić' 'UWAGA' '')) }

    try {
        $smart = @(Get-CimInstance -Namespace 'root/wmi' -ClassName MSStorageDriver_FailurePredictStatus -ErrorAction Stop | Where-Object { $_.PredictFailure })
        if ($smart.Count -gt 0) {
            [void]$wyniki.Add((Wynik-Sprawdzenia 'SMART' ('dysk przewiduje awarię (' + $smart.Count + ')') 'ŹLE' 'Dysk sam zgłasza, że niedługo może się zepsuć - natychmiast potrzebna kopia danych i wymiana.'))
        }
    } catch { }

    # Wolne miejsce
    try {
        foreach ($v in @(Get-CimInstance -ClassName Win32_LogicalDisk -Filter 'DriveType=3' -ErrorAction Stop)) {
            if (-not $v.Size) { continue }
            $proc = [math]::Round(100 * $v.FreeSpace / $v.Size)
            $txt = 'wolne ' + (Tekst-Rozmiaru $v.FreeSpace) + ' z ' + (Tekst-Rozmiaru $v.Size) + ' (' + $proc + '%)'
            if ($proc -lt 10) { $o = 'ŹLE'; $r = 'Bardzo mało miejsca - Windows zwalnia i może nie zainstalować aktualizacji. Warto usunąć zbędne pliki.' }
            elseif ($proc -lt 20) { $o = 'UWAGA'; $r = 'Mało miejsca - warto usunąć zbędne pliki.' }
            else { $o = 'OK'; $r = '' }
            [void]$wyniki.Add((Wynik-Sprawdzenia ('Miejsce na dysku ' + $v.DeviceID) $txt $o $r))
        }
    } catch { }

    # Karta graficzna
    try {
        foreach ($g in @(Get-CimInstance -ClassName Win32_VideoController -ErrorAction Stop)) {
            $n = [string]$g.Name
            if ($n -match 'Remote Display|Indirect Display|Virtual Display') { continue }
            if ($n -match 'Microsoft Basic Display|Podstawowa karta') {
                [void]$wyniki.Add((Wynik-Sprawdzenia 'Karta graficzna' $n 'ŹLE' 'Brak sterownika karty graficznej - do zainstalowania ze strony producenta (Intel, AMD, NVIDIA).'))
                continue
            }
            $txt = $n + '; sterownik ' + $g.DriverVersion
            if ($g.DriverDate) { $txt = $txt + ' z ' + $g.DriverDate.ToString('yyyy-MM-dd') }
            [void]$wyniki.Add((Wynik-Sprawdzenia 'Karta graficzna' $txt 'OK' ''))
        }
    } catch { }

    # Bateria
    try {
        $bat = @(Get-CimInstance -ClassName Win32_Battery -ErrorAction Stop)
        if ($bat.Count -gt 0) {
            $txt = 'naładowana w ' + $bat[0].EstimatedChargeRemaining + '%'
            $ocena = 'INFO'; $rada = 'Pełny raport: przycisk "Raport baterii".'
            try {
                $proj = [double](@(Get-CimInstance -Namespace 'root/wmi' -ClassName BatteryStaticData -ErrorAction Stop) | Measure-Object -Property DesignedCapacity -Sum).Sum
                $pel = [double](@(Get-CimInstance -Namespace 'root/wmi' -ClassName BatteryFullChargedCapacity -ErrorAction Stop) | Measure-Object -Property FullChargedCapacity -Sum).Sum
                if ($proj -gt 0 -and $pel -gt 0) {
                    $zuz = [int][math]::Max(0, [math]::Round(100 - 100 * $pel / $proj))
                    $txt = $txt + '; pojemność ' + [math]::Round($pel / 1000, 1) + ' z ' + [math]::Round($proj / 1000, 1) + ' Wh, zużycie ' + $zuz + '%'
                    if ($zuz -ge 50) { $ocena = 'ŹLE'; $rada = 'Bateria mocno zużyta - zalecana wymiana.' }
                    elseif ($zuz -ge 30) { $ocena = 'UWAGA'; $rada = 'Bateria wyraźnie zużyta - działa krócej niż nowa.' }
                    else { $ocena = 'OK'; $rada = '' }
                }
            } catch { }
            [void]$wyniki.Add((Wynik-Sprawdzenia 'Bateria' $txt $ocena $rada))
        }
    } catch { }

    # Windows: wersja, data instalacji, aktywacja, klucz
    try {
        $txt = $infoOS
        if ($os.InstallDate) {
            $lat = [math]::Round(((Get-Date) - $os.InstallDate).TotalDays / 365, 1)
            $txt = $txt + '; zainstalowany ' + $os.InstallDate.ToString('yyyy-MM-dd') + ' (ok. ' + $lat + ' lat temu)'
        }
        [void]$wyniki.Add((Wynik-Sprawdzenia 'Windows' $txt 'INFO' ''))
    } catch { }
    try {
        $lic = @(Get-CimInstance -ClassName SoftwareLicensingProduct -Filter "ApplicationID='55c92734-d682-4d71-983e-d6ec3f16059f' AND PartialProductKey IS NOT NULL" -ErrorAction Stop)
        $akt = @($lic | Where-Object { $_.LicenseStatus -eq 1 })
        if ($akt.Count -gt 0) {
            [void]$wyniki.Add((Wynik-Sprawdzenia 'Aktywacja Windows' ('aktywowany (' + [string]$akt[0].ProductKeyChannel + ')') 'OK' ''))
        } else {
            [void]$wyniki.Add((Wynik-Sprawdzenia 'Aktywacja Windows' 'NIEAKTYWOWANY' 'ŹLE' 'Windows wymaga aktywacji (Ustawienia > System > Aktywacja).'))
        }
    } catch { }
    try {
        $klucz = [string](Get-CimInstance -ClassName SoftwareLicensingService -ErrorAction Stop).OA3xOriginalProductKey
        if ($klucz.Length -ge 5) {
            $stan.KluczWindows = $klucz
            [void]$wyniki.Add((Wynik-Sprawdzenia 'Klucz Windows w BIOS/UEFI' ('XXXXX-XXXXX-XXXXX-XXXXX-' + $klucz.Substring($klucz.Length - 5)) 'INFO' 'Pełny klucz: przycisk "Kopiuj klucz Windows".'))
        } else {
            [void]$wyniki.Add((Wynik-Sprawdzenia 'Klucz Windows w BIOS/UEFI' 'brak (komputer składany albo licencja cyfrowa)' 'INFO' 'Przy licencji cyfrowej Windows aktywuje się sam po reinstalacji.'))
        }
    } catch { }

    # Czas uruchamiania
    try {
        $cz = Podsumuj-CzasStartu @(Pobierz-CzasyStartu) (Poczatek-Serwisu)
        $stan.CzasStartu = $cz
        if ($cz) {
            $txt = 'ostatnio ' + $cz.Ostatni + ' s (' + $cz.Kiedy.ToString('yyyy-MM-dd HH:mm') + '), średnio ' + $cz.Srednio + ' s'
            if ($null -ne $cz.Przed -and $null -ne $cz.Po) { $txt = $txt + '; przed serwisem ' + $cz.Przed + ' s, po serwisie ' + $cz.Po + ' s' }
            if ($cz.Ostatni -gt 90) { $o = 'UWAGA'; $r = 'Długie uruchamianie - warto ograniczyć programy startowe; dysk SSD przyspieszy start.' }
            elseif ($cz.Ostatni -gt 45) { $o = 'INFO'; $r = 'Start mógłby być szybszy - warto ograniczyć programy startowe.' }
            else { $o = 'OK'; $r = '' }
            [void]$wyniki.Add((Wynik-Sprawdzenia 'Czas uruchamiania Windows' $txt $o $r))
        }
    } catch {
        [void]$wyniki.Add((Wynik-Sprawdzenia 'Czas uruchamiania Windows' 'brak danych (potrzebne uprawnienia administratora)' 'INFO' ''))
    }

    # Urzadzenia z problemami
    try {
        $problemy = @(Get-CimInstance -ClassName Win32_PnPEntity -Filter 'ConfigManagerErrorCode <> 0' -ErrorAction Stop |
            Where-Object { @(22, 24, 45) -notcontains [int]$_.ConfigManagerErrorCode })
        if ($problemy.Count -eq 0) {
            [void]$wyniki.Add((Wynik-Sprawdzenia 'Sterowniki urządzeń' 'wszystkie urządzenia działają' 'OK' ''))
        }
        foreach ($u in @($problemy | Select-Object -First 10)) {
            $n = [string]$u.Name
            if (-not $n) { $n = 'Nieznane urządzenie' }
            [void]$wyniki.Add((Wynik-Sprawdzenia 'Urządzenie z problemem' ($n + ' - ' + (Opis-BleduUrzadzenia $u.ConfigManagerErrorCode)) 'ŹLE' 'Brak lub błąd sterownika - do zainstalowania ze strony producenta albo z Windows Update.'))
        }
    } catch { }

    $wyniki
}

# =====================================================================
#  FUNKCJE: APLIKACJE ZE SKLEPU
# =====================================================================
function Pasuje-Do([string]$nazwa, $wzorce) {
    foreach ($w in $wzorce) { if ($nazwa -like $w) { return $true } }
    $false
}

function Pobierz-Aplikacje {
    $zainstalowane = @()
    try {
        if ($czyAdmin) { $zainstalowane = @(Get-AppxPackage -AllUsers -ErrorAction Stop) }
        else { $zainstalowane = @(Get-AppxPackage -ErrorAction Stop) }
    } catch {
        try { $zainstalowane = @(Get-AppxPackage -ErrorAction Stop) } catch { Log ('Nie udało się pobrać listy aplikacji: ' + $_.Exception.Message) }
    }
    $prov = @()
    if ($czyAdmin) { try { $prov = @(Get-AppxProvisionedPackage -Online -ErrorAction Stop) } catch { } }
    foreach ($a in $listaAplikacji) {
        $znalezione = @($zainstalowane | Where-Object { Pasuje-Do $_.Name $a.Wzorce })
        $znalezioneProv = @($prov | Where-Object { Pasuje-Do $_.DisplayName $a.Wzorce })
        if ($znalezione.Count -eq 0 -and $znalezioneProv.Count -eq 0) { continue }
        $nazwy = @(@($znalezione | ForEach-Object { $_.Name }) + @($znalezioneProv | ForEach-Object { $_.DisplayName }) | Sort-Object -Unique)
        [pscustomobject]@{ Aplikacja = $a; Etykieta = $a.Etykieta; Rodzaj = $a.Rodzaj; Kategoria = $a.Kategoria
            Pakiety = $znalezione; Prov = $znalezioneProv; Nazwy = ($nazwy -join ', '); Office = $null }
    }
    foreach ($o in @(Pobierz-Office)) {
        $opis = 'Pakiet Office (' + $o.Rodzaj + ', wersja ' + $o.Wersja + '). Odinstalowanie po cichu, kilka minut na pakiet; licencja zostaje na koncie Microsoft albo kluczu klienta.'
        [pscustomobject]@{ Aplikacja = [pscustomobject]@{ Opis = $opis }; Etykieta = $o.Nazwa; Rodzaj = 'Opcjonalne'; Kategoria = 'Office'
            Pakiety = @(); Prov = @(); Nazwy = $o.Rodzaj; Office = $o }
    }
}

function Usun-Aplikacje($element) {
    if ($element.Office) { return (Usun-Office $element.Office) }
    $bledy = 0
    foreach ($p in @($element.Pakiety | Sort-Object -Property PackageFullName -Unique)) {
        [System.Windows.Forms.Application]::DoEvents()
        try { Remove-AppxPackage -Package $p.PackageFullName -AllUsers -ErrorAction Stop }
        catch {
            try { Remove-AppxPackage -Package $p.PackageFullName -ErrorAction Stop }
            catch { $bledy++; Log ('  ' + $p.Name + ': ' + $_.Exception.Message) }
        }
    }
    foreach ($p in @($element.Prov)) {
        try { Remove-AppxProvisionedPackage -Online -PackageName $p.PackageName -ErrorAction Stop | Out-Null }
        catch { Log ('  (dla nowych kont) ' + $p.DisplayName + ': ' + $_.Exception.Message) }
    }
    ($bledy -eq 0)
}

# =====================================================================
#  FUNKCJE: INSTALACJA PRZEZ WINGET
# =====================================================================
function Sciezka-Winget {
    $c = Get-Command -Name 'winget.exe' -CommandType Application -ErrorAction SilentlyContinue | Select-Object -First 1
    if ($c) { return $c.Path }
    $p = Join-Path $env:LOCALAPPDATA 'Microsoft\WindowsApps\winget.exe'
    if (Test-Path -LiteralPath $p) { return $p }
    $d = @(Get-ChildItem -Path (Join-Path $env:ProgramFiles 'WindowsApps\Microsoft.DesktopAppInstaller_*_x64__8wekyb3d8bbwe\winget.exe') -ErrorAction SilentlyContinue |
        Sort-Object -Property FullName -Descending)
    if ($d.Count -gt 0) { return $d[0].FullName }
    $null
}

function Pobierz-ZainstalowaneWinget([string]$winget) {
    $plik = Join-Path $env:TEMP ('winget_' + [guid]::NewGuid().ToString('N') + '.json')
    [void](Uruchom-Program ('"' + $winget + '" export -o "' + $plik + '" --accept-source-agreements') 'sprawdzanie programów')
    $ids = @()
    if (Test-Path -LiteralPath $plik) {
        try {
            $j = Get-Content -LiteralPath $plik -Raw -Encoding UTF8 | ConvertFrom-Json
            $ids = @($j.Sources | ForEach-Object { $_.Packages } | ForEach-Object { [string]$_.PackageIdentifier })
        } catch { }
        Remove-Item -LiteralPath $plik -Force -ErrorAction SilentlyContinue
    }
    $ids
}

function Opis-KoduWinget([int]$kod, [string]$tekst) {
    if ($kod -eq 0) { return 'OK' }
    if ($kod -eq -1978335135 -or $kod -eq -1978335189) { return 'już zainstalowany' }
    if ($kod -eq -1978335212) { return 'nie znaleziono w repozytorium' }
    'błąd (kod ' + $kod + ') ' + (@(Ostatnie-Linie $tekst 1) -join ' ')
}

function Zainstaluj-Program([string]$winget, $program) {
    $w = Uruchom-Program ('"' + $winget + '" install --id "' + $program.Id + '" -e --source winget --silent --accept-package-agreements --accept-source-agreements') ('instalacja ' + $program.Etykieta)
    Opis-KoduWinget $w.Kod $w.Tekst
}

# =====================================================================
#  FUNKCJE: PROGRAMY I FOLDERY
# =====================================================================
function Lista-Programow {
    $klucze = @('HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*',
        'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*',
        (Mapuj-Klucz 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Uninstall\*'))
    $lista = foreach ($k in $klucze) {
        Get-ItemProperty -Path $k -ErrorAction SilentlyContinue |
            Where-Object { $_.DisplayName -and $_.SystemComponent -ne 1 -and -not $_.ParentKeyName }
    }
    @($lista | ForEach-Object {
        [pscustomobject]@{ Nazwa = ([string]$_.DisplayName).Trim(); Wersja = [string]$_.DisplayVersion; Wydawca = [string]$_.Publisher }
    } | Sort-Object -Property Nazwa -Unique)
}

function Rozmiar-Folderu([string]$sciezka) {
    if (-not $sciezka -or -not (Test-Path -LiteralPath $sciezka)) { return [long]0 }
    $s = (Get-ChildItem -LiteralPath $sciezka -Recurse -Force -File -ErrorAction SilentlyContinue | Measure-Object -Property Length -Sum).Sum
    if ($s) { [long]$s } else { [long]0 }
}

# =====================================================================
#  FUNKCJE: PAKIETY OFFICE (Click-to-Run i MSI)
# =====================================================================
$procesyOffice = @('WINWORD', 'EXCEL', 'POWERPNT', 'OUTLOOK', 'ONENOTE', 'ONENOTEM', 'MSACCESS', 'MSPUB', 'VISIO', 'WINPROJ', 'lync', 'GROOVE', 'MSOSYNC')

function Pobierz-Office {
    $klucze = @('HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*',
        'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*')
    $lista = foreach ($k in $klucze) {
        Get-ItemProperty -Path $k -ErrorAction SilentlyContinue | Where-Object {
            $_.DisplayName -and $_.UninstallString -and $_.SystemComponent -ne 1 -and
            ([string]$_.UninstallString -match 'OfficeClickToRun\.exe|Office Setup Controller')
        }
    }
    $wynik = foreach ($o in @($lista | Sort-Object -Property DisplayName -Unique)) {
        $c2r = ([string]$o.UninstallString -match 'OfficeClickToRun\.exe')
        $rodzaj = 'MSI'
        if ($c2r) { $rodzaj = 'Click-to-Run' }
        [pscustomobject]@{ Nazwa = ([string]$o.DisplayName).Trim(); Wersja = [string]$o.DisplayVersion; Polecenie = [string]$o.UninstallString
            Rodzaj = $rodzaj; Klucz = [string]$o.PSPath }
    }
    @($wynik)
}

function Usun-Office($o) {
    Stop-Process -Name $procesyOffice -Force -ErrorAction SilentlyContinue
    if ($o.Rodzaj -eq 'Click-to-Run') {
        $polecenie = $o.Polecenie + ' DisplayLevel=False'
    } else {
        # MSI (Office 2010-2016): setup.exe /uninstall PRODUKT + plik konfiguracji z trybem cichym
        $produkt = 'PROPLUS'
        if ($o.Polecenie -match '/uninstall\s+(\S+)') { $produkt = $Matches[1] }
        $xml = Join-Path $env:TEMP ('office_usun_' + $produkt + '.xml')
        $tresc = '<Configuration Product="' + $produkt + '"><Display Level="none" CompletionNotice="no" SuppressModal="yes" AcceptEula="yes" />' +
            '<Setting Id="SETUP_REBOOT" Value="Never" /></Configuration>'
        Set-Content -LiteralPath $xml -Value $tresc -Encoding ASCII
        $polecenie = $o.Polecenie + ' /config "' + $xml + '"'
    }
    Log ('  ' + $o.Nazwa + ': odinstalowuję po cichu (' + $o.Rodzaj + ')...')
    $w = Uruchom-Program $polecenie ('odinstalowanie ' + $o.Nazwa)
    # Click-to-Run konczy prace w tle - czekamy, az wpis zniknie z listy programow (maks. 25 min)
    $start = Get-Date
    $ostatni = Get-Date
    while ((Test-Path -LiteralPath $o.Klucz) -and ((Get-Date) - $start).TotalMinutes -lt 25) {
        [System.Windows.Forms.Application]::DoEvents()
        Start-Sleep -Milliseconds 500
        if (((Get-Date) - $ostatni).TotalSeconds -ge 60) {
            $ostatni = Get-Date
            Log ('  ' + $o.Nazwa + ': trwa (' + [int]((Get-Date) - $start).TotalMinutes + ' min)...')
        }
    }
    $ok = -not (Test-Path -LiteralPath $o.Klucz)
    if (-not $ok) { Log ('  ' + $o.Nazwa + ': deinstalator zakończył się (kod ' + $w.Kod + '), ale program nadal jest na liście. Uruchom ponownie komputer i sprawdź jeszcze raz.') }
    $ok
}

# =====================================================================
#  FUNKCJE: KONTO KLIENTA I PROFILE UZYTKOWNIKOW
# =====================================================================
function Lista-Profili {
    $lista = foreach ($k in @(Get-ChildItem -LiteralPath 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\ProfileList' -ErrorAction SilentlyContinue)) {
        $sid = $k.PSChildName
        if ($sid -notmatch '^S-1-5-21-' -and $sid -notmatch '^S-1-12-1-') { continue }
        $sciezka = [Environment]::ExpandEnvironmentVariables([string](Get-ItemProperty -LiteralPath $k.PSPath -ErrorAction SilentlyContinue).ProfileImagePath)
        if (-not $sciezka -or -not (Test-Path -LiteralPath $sciezka)) { continue }
        $nazwa = Split-Path -Path $sciezka -Leaf
        try { $nazwa = (New-Object System.Security.Principal.SecurityIdentifier($sid)).Translate([System.Security.Principal.NTAccount]).Value } catch { }
        [pscustomobject]@{ Sid = $sid; Sciezka = $sciezka; Nazwa = $nazwa; Zaladowany = (Test-Path -LiteralPath ('Registry::HKEY_USERS\' + $sid)) }
    }
    @($lista | Sort-Object -Property Nazwa)
}

function Uzytkownik-Interaktywny {
    # konto, na ktorym ktos siedzi przy komputerze (nie konto, ktorym potwierdzono uprawnienia)
    try {
        $nazwa = [string](Get-CimInstance -ClassName Win32_ComputerSystem -ErrorAction Stop).UserName
        if ($nazwa) {
            return (New-Object System.Security.Principal.NTAccount($nazwa)).Translate([System.Security.Principal.SecurityIdentifier]).Value
        }
    } catch { }
    try {
        $proc = Get-CimInstance -ClassName Win32_Process -Filter "Name='explorer.exe'" -ErrorAction Stop | Select-Object -First 1
        if ($proc) { return [string](Invoke-CimMethod -InputObject $proc -MethodName GetOwnerSid -ErrorAction Stop).Sid }
    } catch { }
    $null
}

function Rozwin-Sciezke([string]$wartosc, $profil) {
    $w = $wartosc -replace '%USERPROFILE%', $profil.Sciezka.Replace('$', '$$')
    $srodowisko = 'Registry::HKEY_USERS\' + $profil.Sid + '\Environment'
    foreach ($m in [regex]::Matches($w, '%([^%]+)%')) {
        $zmienna = ''
        if (Test-Path -LiteralPath $srodowisko) { $zmienna = [string](Get-Item -LiteralPath $srodowisko).GetValue($m.Groups[1].Value) }
        if (-not $zmienna) { $zmienna = [Environment]::GetEnvironmentVariable($m.Groups[1].Value) }
        if ($zmienna) { $w = $w.Replace($m.Value, $zmienna) }
    }
    $w
}

function Foldery-Profilu($profil) {
    $nazwy = [ordered]@{
        Pulpit = @('Desktop', 'Desktop'); Dokumenty = @('Personal', 'Documents'); Obrazy = @('My Pictures', 'Pictures')
        Pobrane = @('{374DE290-123F-4565-9164-39C4925E467B}', 'Downloads'); Muzyka = @('My Music', 'Music'); Wideo = @('My Video', 'Videos')
    }
    $wynik = @{}
    $klucz = 'Registry::HKEY_USERS\' + $profil.Sid + '\Software\Microsoft\Windows\CurrentVersion\Explorer\User Shell Folders'
    $jestKlucz = $profil.Zaladowany -and (Test-Path -LiteralPath $klucz)
    foreach ($n in $nazwy.Keys) {
        $sciezka = ''
        if ($jestKlucz) {
            $v = [string](Get-Item -LiteralPath $klucz).GetValue($nazwy[$n][0], '', 'DoNotExpandEnvironmentNames')
            if ($v) { $sciezka = Rozwin-Sciezke $v $profil }
        }
        if (-not $sciezka -or -not (Test-Path -LiteralPath $sciezka)) {
            $domyslna = Join-Path $profil.Sciezka $nazwy[$n][1]
            $chmura = Join-Path $profil.Sciezka ('OneDrive\' + $nazwy[$n][1])
            if (Test-Path -LiteralPath $domyslna) { $sciezka = $domyslna }
            elseif (Test-Path -LiteralPath $chmura) { $sciezka = $chmura }
            else { $sciezka = $domyslna }
        }
        $wynik[$n] = $sciezka
    }
    $wynik
}

function Ustal-KontoKlienta {
    $stan.Ja = [Security.Principal.WindowsIdentity]::GetCurrent().User.Value
    $stan.Profile = @(Lista-Profili)
    $sid = Uzytkownik-Interaktywny
    $klient = $null
    if ($sid) { $klient = $stan.Profile | Where-Object { $_.Sid -eq $sid } | Select-Object -First 1 }
    if (-not $klient) { $klient = $stan.Profile | Where-Object { $_.Sid -eq $stan.Ja } | Select-Object -First 1 }
    if (-not $klient) {
        $klient = [pscustomobject]@{ Sid = $stan.Ja; Sciezka = $env:USERPROFILE; Nazwa = $env:USERNAME; Zaladowany = $true }
        $stan.Profile = @($stan.Profile) + @($klient)
    }
    $stan.Klient = $klient
    $stan.InneKonto = ($klient.Sid -ne $stan.Ja)
    $stan.ProfilKopii = $klient
}

# =====================================================================
#  STEROWNIKI I BIOS
# =====================================================================
# klasa urzadzenia -> rodzaj, waznosc, waga do sortowania
$klasySterownikow = @{
    'DISPLAY'           = @('Karta graficzna', 'Ważne', 0)
    'NET'               = @('Sieć (Wi-Fi, LAN)', 'Ważne', 0)
    'MEDIA'             = @('Dźwięk', 'Ważne', 0)
    'BLUETOOTH'         = @('Bluetooth', 'Ważne', 0)
    'HDC'               = @('Kontroler dysków', 'Ważne', 0)
    'SCSIADAPTER'       = @('Kontroler dysków', 'Ważne', 0)
    'FIRMWARE'          = @('BIOS / firmware', 'BIOS i firmware', 1)
    'SYSTEM'            = @('Chipset i system', 'Mniej ważne', 2)
    'USB'               = @('USB', 'Mniej ważne', 2)
    'CAMERA'            = @('Kamera', 'Mniej ważne', 2)
    'IMAGE'             = @('Kamera / skaner', 'Mniej ważne', 2)
    'BIOMETRIC'         = @('Czytnik linii papilarnych', 'Mniej ważne', 2)
    'HIDCLASS'          = @('Klawiatura, touchpad, pióro', 'Mniej ważne', 2)
    'MOUSE'             = @('Mysz, touchpad', 'Mniej ważne', 2)
    'KEYBOARD'          = @('Klawiatura', 'Mniej ważne', 2)
    'SENSOR'            = @('Czujniki', 'Mniej ważne', 2)
    'BATTERY'           = @('Bateria i zasilanie', 'Mniej ważne', 2)
    'SOFTWARECOMPONENT' = @('Dodatki producenta', 'Mniej ważne', 2)
    'EXTENSION'         = @('Rozszerzenia sterowników', 'Mniej ważne', 2)
    'PRINTER'           = @('Drukarka', 'Mniej ważne', 2)
    'MONITOR'           = @('Monitor', 'Mniej ważne', 2)
}
$klasyNaLiscie = @('DISPLAY', 'NET', 'MEDIA', 'BLUETOOTH', 'HDC', 'SCSIADAPTER', 'FIRMWARE', 'SYSTEM', 'CAMERA', 'IMAGE', 'BIOMETRIC', 'SENSOR')

function Rodzaj-Sterownika([string]$klasa) {
    $k = ([string]$klasa).ToUpper()
    if ($klasySterownikow.ContainsKey($k)) { return $klasySterownikow[$k] }
    @(('Inne (' + $klasa + ')'), 'Mniej ważne', 2)
}

function Pasuje-Sprzet([string]$a, [string]$b) {
    if (-not $a -or -not $b) { return $false }
    $a = $a.ToUpper(); $b = $b.ToUpper()
    $a.StartsWith($b) -or $b.StartsWith($a)
}

function Nowy-Sterownik($nazwa, $klasa, $wersja, $data, $producent, $sprzet, $urzadzenie) {
    $r = Rodzaj-Sterownika $klasa
    [pscustomobject]@{ Nazwa = $nazwa; Rodzaj = $r[0]; Waznosc = $r[1]; Waga = $r[2]; Wersja = $wersja; Data = $data
        Producent = $producent; Sprzet = $sprzet; Urzadzenie = $urzadzenie; Aktualizacja = $null }
}

function Pobierz-Sterowniki {
    $wynik = New-Object System.Collections.ArrayList
    # BIOS / UEFI zawsze na gorze
    try {
        $bios = Get-CimInstance -ClassName Win32_BIOS -ErrorAction Stop
        $cs = Get-CimInstance -ClassName Win32_ComputerSystem -ErrorAction SilentlyContinue
        $data = $null
        if ($bios.ReleaseDate) { $data = $bios.ReleaseDate }
        $b = Nowy-Sterownik ('BIOS / UEFI: ' + ([string]$cs.Manufacturer).Trim() + ' ' + ([string]$cs.Model).Trim()) 'FIRMWARE' ([string]$bios.SMBIOSBIOSVersion) $data ([string]$bios.Manufacturer) '' ''
        $b.Waga = 0.5
        [void]$wynik.Add($b)
    } catch { }
    $sterowniki = @(Get-CimInstance -ClassName Win32_PnPSignedDriver -ErrorAction Stop | Where-Object {
        $_.DeviceName -and $_.DeviceClass -and ($klasyNaLiscie -contains ([string]$_.DeviceClass).ToUpper()) -and
        (([string]$_.DriverProviderName -ne 'Microsoft') -or ([string]$_.DeviceClass).ToUpper() -eq 'DISPLAY')
    })
    foreach ($g in @($sterowniki | Group-Object -Property DeviceName)) {
        $s = $g.Group[0]
        [void]$wynik.Add((Nowy-Sterownik ([string]$s.DeviceName) ([string]$s.DeviceClass) ([string]$s.DriverVersion) $s.DriverDate ([string]$s.DriverProviderName) ([string]$s.HardWareID) ([string]$s.DeviceID)))
    }
    $wynik
}

function Opis-Wersji($s) {
    $t = [string]$s.Wersja
    if ($s.Data) { try { $t = $t + ' (' + ([datetime]$s.Data).ToString('yyyy-MM-dd') + ')' } catch { } }
    if ($s.Producent) { $t = $t + $NL + $s.Producent }
    $t
}

# --- Windows Update: osobny proces PowerShella, zeby okno nie zawieszalo sie podczas szukania ---
$skryptWUWspolny = @'
function Szukaj-Sterownikow($sesja) {
    $szukacz = $sesja.CreateUpdateSearcher()
    $blad = ''
    foreach ($serwer in @(2, 0)) {
        try {
            $szukacz.ServerSelection = $serwer
            return $szukacz.Search("IsInstalled=0 and Type='Driver' and IsHidden=0")
        } catch { $blad = $_.Exception.Message }
    }
    throw $blad
}
'@

$skryptWUSzukaj = 'param([string]$wyjscie)' + "`r`n" + $skryptWUWspolny + @'

try {
    $sesja = New-Object -ComObject Microsoft.Update.Session
    $sesja.ClientApplicationID = 'Narzedzia serwisowe'
    $wynik = Szukaj-Sterownikow $sesja
    $lista = @(foreach ($u in $wynik.Updates) {
        $data = ''
        try { $data = ([datetime]$u.DriverVerDate).ToString('yyyy-MM-dd') } catch { }
        [pscustomobject]@{ Id = [string]$u.Identity.UpdateID; Tytul = [string]$u.Title; Klasa = [string]$u.DriverClass
            Producent = [string]$u.DriverManufacturer; Model = [string]$u.DriverModel; Data = $data
            Sprzet = [string]$u.DriverHardwareID; Rozmiar = [long]$u.MaxDownloadSize }
    })
    ConvertTo-Json -InputObject @{ Ok = $true; Lista = $lista } -Depth 4 | Set-Content -LiteralPath $wyjscie -Encoding UTF8
} catch {
    ConvertTo-Json -InputObject @{ Ok = $false; Blad = $_.Exception.Message } | Set-Content -LiteralPath $wyjscie -Encoding UTF8
}
'@

$skryptWUInstaluj = 'param([string]$plikIds, [string]$wyjscie)' + "`r`n" + $skryptWUWspolny + @'

try {
    $ids = @(Get-Content -LiteralPath $plikIds | Where-Object { $_ })
    $sesja = New-Object -ComObject Microsoft.Update.Session
    $sesja.ClientApplicationID = 'Narzedzia serwisowe'
    $wynik = Szukaj-Sterownikow $sesja
    $kolekcja = New-Object -ComObject Microsoft.Update.UpdateColl
    foreach ($u in $wynik.Updates) {
        if ($ids -contains [string]$u.Identity.UpdateID) {
            if (-not $u.EulaAccepted) { $u.AcceptEula() }
            [void]$kolekcja.Add($u)
        }
    }
    if ($kolekcja.Count -eq 0) { throw 'Nie znaleziono wybranych aktualizacji (może są już zainstalowane).' }
    $pobieranie = $sesja.CreateUpdateDownloader()
    $pobieranie.Updates = $kolekcja
    [void]$pobieranie.Download()
    $instalator = $sesja.CreateUpdateInstaller()
    $instalator.Updates = $kolekcja
    $instalator.AllowSourcePrompts = $false
    $w = $instalator.Install()
    $wyniki = @(for ($i = 0; $i -lt $kolekcja.Count; $i++) {
        [pscustomobject]@{ Id = [string]$kolekcja.Item($i).Identity.UpdateID; Tytul = [string]$kolekcja.Item($i).Title; Kod = [int]$w.GetUpdateResult($i).ResultCode }
    })
    ConvertTo-Json -InputObject @{ Ok = $true; Restart = [bool]$w.RebootRequired; Wyniki = $wyniki } -Depth 4 | Set-Content -LiteralPath $wyjscie -Encoding UTF8
} catch {
    ConvertTo-Json -InputObject @{ Ok = $false; Blad = $_.Exception.Message } | Set-Content -LiteralPath $wyjscie -Encoding UTF8
}
'@

function Uruchom-SkryptWU([string]$skrypt, [string[]]$argumenty, [string]$opis) {
    $plik = Join-Path $env:TEMP ('serwis_wu_' + [guid]::NewGuid().ToString('N') + '.ps1')
    [IO.File]::WriteAllText($plik, $skrypt, (New-Object System.Text.UTF8Encoding($true)))
    $wyjscie = $argumenty[-1]
    $polecenie = 'powershell.exe -NoProfile -ExecutionPolicy Bypass -File "' + $plik + '"'
    foreach ($a in $argumenty) { $polecenie = $polecenie + ' "' + $a + '"' }
    [void](Uruchom-Program $polecenie $opis)
    Remove-Item -LiteralPath $plik -Force -ErrorAction SilentlyContinue
    $dane = $null
    if (Test-Path -LiteralPath $wyjscie) {
        try { $dane = Get-Content -LiteralPath $wyjscie -Raw -Encoding UTF8 | ConvertFrom-Json } catch { }
        Remove-Item -LiteralPath $wyjscie -Force -ErrorAction SilentlyContinue
    }
    if (-not $dane) { $dane = [pscustomobject]@{ Ok = $false; Blad = 'brak odpowiedzi z Windows Update' } }
    $dane
}

function Szukaj-AktualizacjiSterownikow {
    $wyjscie = Join-Path $env:TEMP ('serwis_wu_' + [guid]::NewGuid().ToString('N') + '.json')
    Uruchom-SkryptWU $skryptWUSzukaj @($wyjscie) 'szukanie sterowników w Windows Update'
}

function Zainstaluj-AktualizacjeSterownikow([string[]]$ids) {
    $plikIds = Join-Path $env:TEMP ('serwis_wu_' + [guid]::NewGuid().ToString('N') + '.txt')
    Set-Content -LiteralPath $plikIds -Value $ids -Encoding ASCII
    $wyjscie = Join-Path $env:TEMP ('serwis_wu_' + [guid]::NewGuid().ToString('N') + '.json')
    $wynik = Uruchom-SkryptWU $skryptWUInstaluj @($plikIds, $wyjscie) 'instalacja sterowników'
    Remove-Item -LiteralPath $plikIds -Force -ErrorAction SilentlyContinue
    $wynik
}

function Opis-WynikuWU([int]$kod) {
    switch ($kod) {
        2       { 'zainstalowano' }
        3       { 'zainstalowano z ostrzeżeniami' }
        4       { 'błąd instalacji' }
        5       { 'przerwano' }
        default { 'kod ' + $kod }
    }
}

# --- narzedzia producentow (sprawdzaja tez BIOS) ---
function Narzedzie-Producenta {
    $producent = ''; $procesor = ''
    try { $producent = [string](Get-CimInstance -ClassName Win32_ComputerSystem -ErrorAction Stop).Manufacturer } catch { }
    try { $procesor = [string](Get-CimInstance -ClassName Win32_Processor -ErrorAction Stop | Select-Object -First 1).Manufacturer } catch { }
    if ($producent -match 'Dell') { return [pscustomobject]@{ Etykieta = 'Dell Command | Update'; Id = 'Dell.CommandUpdate.Universal'; Skrot = '*Dell Command*Update*'; Strona = '' } }
    if ($producent -match 'Lenovo') { return [pscustomobject]@{ Etykieta = 'Lenovo System Update'; Id = 'Lenovo.SystemUpdate'; Skrot = '*System Update*'; Strona = '' } }
    if ($producent -match 'HP|Hewlett') { return [pscustomobject]@{ Etykieta = 'HP Support Assistant'; Id = 'HP.SupportAssistant'; Skrot = '*HP Support Assistant*'; Strona = '' } }
    if ($procesor -match 'Intel') {
        return [pscustomobject]@{ Etykieta = 'Intel Driver & Support Assistant'; Id = 'Intel.IntelDriverAndSupportAssistant'; Skrot = ''
            Strona = 'https://www.intel.com/content/www/us/en/support/intel-driver-support-assistant.html' }
    }
    if ($procesor -match 'AMD') { return [pscustomobject]@{ Etykieta = 'Sterowniki AMD'; Id = ''; Skrot = ''; Strona = 'https://www.amd.com/en/support/download/drivers.html' } }
    $null
}

function Znajdz-Skrot([string]$wzor) {
    if (-not $wzor) { return $null }
    $foldery = @((Join-Path $env:ProgramData 'Microsoft\Windows\Start Menu\Programs'))
    if ($stan.Klient) { $foldery += (Join-Path $stan.Klient.Sciezka 'AppData\Roaming\Microsoft\Windows\Start Menu\Programs') }
    foreach ($f in $foldery) {
        $s = Get-ChildItem -LiteralPath $f -Recurse -Filter '*.lnk' -ErrorAction SilentlyContinue | Where-Object { $_.BaseName -like $wzor } | Select-Object -First 1
        if ($s) { return $s.FullName }
    }
    $null
}

function Strona-Producenta {
    $cs = $null; $bios = $null
    try { $cs = Get-CimInstance -ClassName Win32_ComputerSystem -ErrorAction Stop } catch { }
    try { $bios = Get-CimInstance -ClassName Win32_BIOS -ErrorAction Stop } catch { }
    $producent = ([string]$cs.Manufacturer).Trim()
    $model = ([string]$cs.Model).Trim()
    $sn = ([string]$bios.SerialNumber).Trim()
    if ($producent -match 'Dell' -and $sn) {
        return [pscustomobject]@{ Adres = ('https://www.dell.com/support/home/pl-pl/product-support/servicetag/' + $sn + '/drivers'); Numer = $sn }
    }
    $zapytanie = [uri]::EscapeDataString($producent + ' ' + $model + ' sterowniki BIOS')
    [pscustomobject]@{ Adres = ('https://www.google.com/search?q=' + $zapytanie); Numer = $sn }
}

# =====================================================================
#  WYBOR WERSJI: katalog Microsoft Update (wszystkie opublikowane wersje sterownika dla danego sprzetu)
# =====================================================================
function Uruchom-Exe([string]$plik, [string]$argumenty, [string]$opis) {
    # bez cmd.exe (adresy z % nie sa wtedy psute); okno programu dalej reaguje
    $start = Get-Date
    $ostatni = Get-Date
    $proc = Start-Process -FilePath $plik -ArgumentList $argumenty -WindowStyle Hidden -PassThru
    $null = $proc.Handle
    while (-not $proc.HasExited) {
        [System.Windows.Forms.Application]::DoEvents()
        Start-Sleep -Milliseconds 200
        if (((Get-Date) - $ostatni).TotalSeconds -ge 60) {
            $ostatni = Get-Date
            Log ('  ' + $opis + ': trwa (' + [int]((Get-Date) - $start).TotalMinutes + ' min)...')
        }
    }
    $proc.WaitForExit()
    $proc.ExitCode
}

function Pobierz-Plik([string]$adres, [string]$cel, [string]$plikPost, [string]$opis) {
    $curl = Join-Path $env:windir 'System32\curl.exe'
    if (Test-Path -LiteralPath $curl) {
        $arg = '-s -L --fail --max-time 3600 -A "Mozilla/5.0 (Windows NT 10.0; Win64; x64)" -o "' + $cel + '"'
        if ($plikPost) { $arg = $arg + ' -H "Content-Type: application/x-www-form-urlencoded" --data-binary "@' + $plikPost + '"' }
        $arg = $arg + ' "' + $adres + '"'
        $kod = Uruchom-Exe $curl $arg $opis
        return (($kod -eq 0) -and (Test-Path -LiteralPath $cel))
    }
    try {
        [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
        if ($plikPost) {
            Invoke-WebRequest -Uri $adres -Method Post -Body ([IO.File]::ReadAllText($plikPost)) -ContentType 'application/x-www-form-urlencoded' -OutFile $cel -UseBasicParsing -ErrorAction Stop
        } else {
            Invoke-WebRequest -Uri $adres -OutFile $cel -UseBasicParsing -ErrorAction Stop
        }
        return (Test-Path -LiteralPath $cel)
    } catch { return $false }
}

function Tekst-Komorki([string]$html) {
    $t = [System.Net.WebUtility]::HtmlDecode(($html -replace '<[^>]+>', ' '))
    ($t -replace '\s+', ' ').Trim()
}

function Parsuj-Katalog([string]$html) {
    $wyniki = New-Object System.Collections.ArrayList
    foreach ($m in [regex]::Matches($html, '<tr id="([0-9a-fA-F\-]{36})_R\d+"[\s\S]*?</tr>')) {
        $id = $m.Groups[1].Value
        $komorki = @{}
        foreach ($c in [regex]::Matches($m.Value, '<td[^>]*id="' + [regex]::Escape($id) + '_C(\d)_R\d+"[^>]*>([\s\S]*?)</td>')) {
            $komorki[[int]$c.Groups[1].Value] = $c.Groups[2].Value
        }
        if (-not $komorki.ContainsKey(1)) { continue }
        $data = $null
        try { $data = [datetime]::ParseExact((Tekst-Komorki $komorki[4]), 'M/d/yyyy', [Globalization.CultureInfo]::InvariantCulture) } catch { }
        $bajty = [long]0
        $spany = [regex]::Matches([string]$komorki[6], '<span[^>]*>([^<]*)</span>')
        if ($spany.Count -ge 2) { [void][long]::TryParse($spany[1].Groups[1].Value.Trim(), [ref]$bajty) }
        [void]$wyniki.Add([pscustomobject]@{
            Id = $id; Tytul = (Tekst-Komorki $komorki[1]); Produkty = (Tekst-Komorki $komorki[2]); Klasyfikacja = (Tekst-Komorki $komorki[3])
            Data = $data; Wersja = (Tekst-Komorki $komorki[5]); Bajty = $bajty; Zrodlo = 'Katalog Microsoft'; Aktualizacja = $null
        })
    }
    $wyniki
}

function Parsuj-LinkiPobierania([string]$html) {
    $t = $html.Replace('www.download.windowsupdate', 'download.windowsupdate')
    $wzor = "(https?://(?:dl\.delivery\.mp\.microsoft\.com|(?:catalog\.s\.)?download\.windowsupdate\.com)/[^'`"\s]*)"
    @([regex]::Matches($t, $wzor) | ForEach-Object { $_.Groups[1].Value } | Select-Object -Unique)
}

function Zapytania-Katalogu([string]$sprzet) {
    # od najdokladniejszego identyfikatora do ogolnego (producent + model ukladu)
    $lista = New-Object System.Collections.ArrayList
    if (-not $sprzet) { return @() }
    [void]$lista.Add($sprzet)
    if ($sprzet -match '^([^\\]+\\[^&]+&[^&]+)&') { [void]$lista.Add($Matches[1]) }
    @($lista | Select-Object -Unique)
}

function Szukaj-WKatalogu([string]$sprzet) {
    $wszystkie = New-Object System.Collections.ArrayList
    foreach ($q in (Zapytania-Katalogu $sprzet)) {
        $plik = Join-Path $env:TEMP ('serwis_kat_' + [guid]::NewGuid().ToString('N') + '.html')
        $adres = 'https://www.catalog.update.microsoft.com/Search.aspx?q=' + [uri]::EscapeDataString($q)
        if (Pobierz-Plik $adres $plik '' 'katalog Microsoft') {
            $html = [IO.File]::ReadAllText($plik)
            foreach ($w in (Parsuj-Katalog $html)) { if (-not @($wszystkie | Where-Object { $_.Id -eq $w.Id })) { [void]$wszystkie.Add($w) } }
        }
        Remove-Item -LiteralPath $plik -Force -ErrorAction SilentlyContinue
    }
    @($wszystkie | Sort-Object -Property Data -Descending)
}

function Identyfikatory-Urzadzenia([string]$urzadzenie, [string]$sprzet) {
    $ids = @()
    if ($urzadzenie) {
        try {
            $e = Get-CimInstance -ClassName Win32_PnPEntity -Filter ("DeviceID='" + $urzadzenie.Replace('\', '\\').Replace("'", "\'") + "'") -ErrorAction Stop | Select-Object -First 1
            if ($e) { $ids = @($e.HardwareID) + @($e.CompatibleID) }
        } catch { }
    }
    if ($sprzet -and $ids -notcontains $sprzet) { $ids = @($sprzet) + $ids }
    @($ids | Where-Object { $_ })
}

$skryptWymusSterownik = @'
param([string]$sprzet, [string]$inf, [string]$wyjscie)
$ok = $false; $restart = $false; $blad = ''; $metoda = 'wybrana wersja (wymuszona)'
if ($sprzet) {
    try {
        $definicja = '[DllImport("newdev.dll", SetLastError = true, CharSet = CharSet.Unicode)] public static extern bool UpdateDriverForPlugAndPlayDevices(IntPtr hwndParent, string HardwareId, string FullInfPath, uint InstallFlags, out bool bRebootRequired);'
        Add-Type -Namespace 'SerwisSKL' -Name 'Sterownik' -MemberDefinition $definicja -ErrorAction Stop
        $ok = [SerwisSKL.Sterownik]::UpdateDriverForPlugAndPlayDevices([IntPtr]::Zero, $sprzet, $inf, 1, [ref]$restart)
        if (-not $ok) { $blad = 'kod Windows ' + [Runtime.InteropServices.Marshal]::GetLastWin32Error() }
    } catch { $blad = $_.Exception.Message }
}
if (-not $ok) {
    $metoda = 'pnputil'
    $tekst = & pnputil.exe /add-driver $inf /install 2>&1
    if ($LASTEXITCODE -eq 0 -or $LASTEXITCODE -eq 3010) { $ok = $true; if ($LASTEXITCODE -eq 3010) { $restart = $true } }
    else { $blad = $blad + ' / pnputil: ' + ((@($tekst) | Select-Object -Last 2) -join ' ') }
}
ConvertTo-Json -InputObject @{ Ok = $ok; Restart = $restart; Metoda = $metoda; Blad = $blad } | Set-Content -LiteralPath $wyjscie -Encoding UTF8
'@

function Zainstaluj-ZKatalogu($wersja, $sterownik) {
    $folder = Join-Path $env:TEMP ('serwis_sterownik_' + [guid]::NewGuid().ToString('N'))
    New-Item -ItemType Directory -Force -Path $folder | Out-Null
    try {
        # 1. adres pliku z okna pobierania katalogu
        $post = Join-Path $folder 'zapytanie.txt'
        $json = '[{"size":0,"languages":"","uidInfo":"' + $wersja.Id + '","updateID":"' + $wersja.Id + '"}]'
        [IO.File]::WriteAllText($post, ('updateIDs=' + [uri]::EscapeDataString($json)))
        $okno = Join-Path $folder 'pobieranie.html'
        if (-not (Pobierz-Plik 'https://www.catalog.update.microsoft.com/DownloadDialog.aspx' $okno $post 'katalog Microsoft')) { throw 'nie udało się połączyć z katalogiem Microsoft' }
        $linki = @(Parsuj-LinkiPobierania ([IO.File]::ReadAllText($okno)))
        if ($linki.Count -eq 0) { throw 'katalog nie podał adresu pliku' }
        # 2. pobranie i rozpakowanie
        $cab = Join-Path $folder 'sterownik.cab'
        Log ('  pobieram ' + (Tekst-Rozmiaru $wersja.Bajty) + '...')
        $adres = $linki[0]
        if (-not (Pobierz-Plik ($adres -replace '^http:', 'https:') $cab '' 'pobieranie sterownika')) {
            if (-not (Pobierz-Plik $adres $cab '' 'pobieranie sterownika')) { throw 'nie udało się pobrać pliku sterownika' }
        }
        $rozpakowane = Join-Path $folder 'pliki'
        New-Item -ItemType Directory -Force -Path $rozpakowane | Out-Null
        [void](Uruchom-Exe (Join-Path $env:windir 'System32\expand.exe') ('-F:* "' + $cab + '" "' + $rozpakowane + '"') 'rozpakowywanie')
        $infy = @(Get-ChildItem -LiteralPath $rozpakowane -Recurse -Filter '*.inf' -ErrorAction SilentlyContinue)
        if ($infy.Count -eq 0) { throw 'w pobranym pliku nie ma sterownika (.inf)' }
        # 3. plik .inf, ktory obsluguje to urzadzenie, i identyfikator do wymuszenia wersji
        $ids = Identyfikatory-Urzadzenia $sterownik.Urzadzenie $sterownik.Sprzet
        $wybranyInf = $null; $wybranyId = ''
        foreach ($i in $infy) {
            $tresc = [IO.File]::ReadAllText($i.FullName)
            foreach ($id in $ids) {
                if ($tresc.IndexOf($id, [StringComparison]::OrdinalIgnoreCase) -ge 0) { $wybranyInf = $i.FullName; $wybranyId = $id; break }
            }
            if ($wybranyInf) { break }
        }
        if (-not $wybranyInf) { $wybranyInf = $infy[0].FullName }
        # 4. instalacja w osobnym procesie
        $skrypt = Join-Path $folder 'instaluj.ps1'
        [IO.File]::WriteAllText($skrypt, $skryptWymusSterownik, (New-Object System.Text.UTF8Encoding($true)))
        $wyjscie = Join-Path $folder 'wynik.json'
        $arg = '-NoProfile -ExecutionPolicy Bypass -File "' + $skrypt + '" "' + $wybranyId + '" "' + $wybranyInf + '" "' + $wyjscie + '"'
        [void](Uruchom-Exe 'powershell.exe' $arg 'instalacja sterownika')
        if (-not (Test-Path -LiteralPath $wyjscie)) { throw 'instalator nie zwrócił wyniku' }
        Get-Content -LiteralPath $wyjscie -Raw -Encoding UTF8 | ConvertFrom-Json
    } catch {
        [pscustomobject]@{ Ok = $false; Restart = $false; Metoda = ''; Blad = $_.Exception.Message }
    } finally {
        Remove-Item -LiteralPath $folder -Recurse -Force -ErrorAction SilentlyContinue
    }
}

