function Dodaj-DoMenu($kontrolka) {
    $menu.Controls.Add($kontrolka)
    $kontrolka.BringToFront()
}

function Nowa-SekcjaMenu([string]$tekst) {
    $l = New-Object System.Windows.Forms.Label
    $l.Text = $tekst
    $l.Dock = 'Top'
    $l.Height = Px 34
    $l.Font = $czcionkaSekcja
    $l.ForeColor = [System.Drawing.Color]::FromArgb(107, 114, 128)
    $l.TextAlign = 'BottomLeft'
    $l.Padding = New-Object System.Windows.Forms.Padding((Px 18), 0, 0, (Px 5))
    Dodaj-DoMenu $l
}

function Rysuj-PozycjeMenu($l, $e) {
    $d = $l.Tag
    $g = $e.Graphics
    $aktywna = ($zakladki.SelectedTab -eq $d.Zakladka)
    $tlo = $kolorMenu
    if ($aktywna) { $tlo = $kolorMenuAktywne } elseif ($d.Nad) { $tlo = $kolorMenuNad }
    $g.Clear($tlo)
    $kolorTxt = $kolorMenuTekst
    $kolorIk = $kolorMenuTekst
    if ($aktywna) {
        $pedzel = New-Object System.Drawing.SolidBrush($kolorAkcent)
        $g.FillRectangle($pedzel, 0, (Px 6), (Px 4), $l.Height - (Px 12))
        $pedzel.Dispose()
        $kolorTxt = [System.Drawing.Color]::White
        $kolorIk = $kolorAkcent
    } elseif ($d.Nad) {
        $kolorTxt = [System.Drawing.Color]::FromArgb(229, 231, 235)
    }
    $flagiIk = [System.Windows.Forms.TextFormatFlags]'HorizontalCenter, VerticalCenter, NoPadding'
    $flagiTxt = [System.Windows.Forms.TextFormatFlags]'Left, VerticalCenter, EndEllipsis, NoPrefix'
    $prostIk = New-Object System.Drawing.Rectangle((Px 14), 0, (Px 28), $l.Height)
    $prostTxt = New-Object System.Drawing.Rectangle((Px 48), 0, [math]::Max(10, $l.Width - (Px 54)), $l.Height)
    [System.Windows.Forms.TextRenderer]::DrawText($g, $d.Ikona, $czcionkaIkon, $prostIk, $kolorIk, $flagiIk)
    [System.Windows.Forms.TextRenderer]::DrawText($g, $d.Tekst, $czcionkaMenu, $prostTxt, $kolorTxt, $flagiTxt)
}

function Nowa-PozycjaMenu([int]$kodIkony, [string]$tekst, $zakladka) {
    $l = New-Object System.Windows.Forms.Label
    $l.Dock = 'Top'
    $l.Height = Px 40
    $l.Cursor = [System.Windows.Forms.Cursors]::Hand
    $l.Tag = @{ Ikona = [string][char]$kodIkony; Tekst = $tekst; Zakladka = $zakladka; Nad = $false }
    $l.Add_Paint({ param($nadawca, $e) Rysuj-PozycjeMenu $nadawca $e })
    $l.Add_MouseEnter({ param($nadawca, $e) $nadawca.Tag.Nad = $true; $nadawca.Invalidate() })
    $l.Add_MouseLeave({ param($nadawca, $e) $nadawca.Tag.Nad = $false; $nadawca.Invalidate() })
    $l.Add_Click({ param($nadawca, $e) if ($zakladki.Enabled) { $zakladki.SelectedTab = $nadawca.Tag.Zakladka } })
    Dodaj-DoMenu $l
    [void]$stan.Menu.Add($l)
}

