function Wypelnij-Czyszczenie {
    $siatkaC.Rows.Clear()
    foreach ($p in $listaCzyszczenia) {
        $p | Add-Member -NotePropertyName 'Bajty' -NotePropertyValue ([long]-1) -Force
        $idx = $siatkaC.Rows.Add($false, $p.Etykieta, $p.Opis, '...')
        $wiersz = $siatkaC.Rows[$idx]
        $wiersz.Tag = $p
