if ($win32) {
    try {
        $konsola = $win32::GetConsoleWindow()
        if ($konsola -ne [IntPtr]::Zero -and $win32::IsWindowVisible($konsola)) {
            [void]$win32::ShowWindow($konsola, 0)
            $konsolaUkryta = $true
        }
    } catch { }
}

